package project.init.account.config.database;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.data.jpa.repository.config.EnableJpaRepositories;import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;import org.springframework.transaction.PlatformTransactionManager;import project.init.account.domain.properties.DatabaseProperties;import javax.sql.DataSource;@Configuration@EnableJpaRepositories(        basePackages = "project.init.account.repository",        entityManagerFactoryRef = "accountEntityManager",        transactionManagerRef = "accountTransactionManager")public class Account {    @Bean()    @ConfigurationProperties(prefix = "app.account.datasource.postgres")    public DatabaseProperties accountDBProperties() {        return new DatabaseProperties();    }    @Bean()    public DataSource accountDataSource() {        return Factory.createDataSource(accountDBProperties());    }    @Bean(name = "accountEntityManager")    public LocalContainerEntityManagerFactoryBean accountEntityManager() {        return Factory.createEntityManager(accountDataSource(), "project.init.account.domain");    }    @Bean(name = "accountTransactionManager")    public PlatformTransactionManager accountTransactionManager() {        return Factory.createTransactionManager(accountEntityManager());    }}